def f(n):
    result = []

    def factorial(x):
        if x == 0:
            return 1
        else:
            return x * factorial(x - 1)

    def sum_of_numbers(start, end):
        return (end * (end + 1)) // 2 - (start * (start - 1)) // 2

    for i in range(n):
        if i % 2 == 0:
            result.append(factorial(i + 1))
        else:
            result.append(sum_of_numbers(1, i + 1))

    return result
